function voiceText(){return voiceCopy[locale]||voiceCopy.en}
function voiceMimeType(){return ["audio/webm;codecs=opus","audio/mp4","audio/webm","audio/ogg;codecs=opus"].find(type=>MediaRecorder.isTypeSupported(type))||""}
function blobAsDataURL(blob){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob)})}
function resetVoiceRecorder(){clearTimeout(voiceStopTimer);voiceStopTimer=null;voiceStream?.getTracks().forEach(track=>track.stop());voiceStream=null;voiceRecorder=null;voiceChunks=[];const button=$("#recordVoice"),status=$("#voiceStatus");if(button){button.classList.remove("recording");button.textContent="🎤";button.setAttribute("aria-label",voiceText().record)}if(status)status.textContent=""}
async function sendVoiceRecording(connectionId,blob,duration){const status=$("#voiceStatus");if(blob.size>130000){toast(voiceText().tooLarge);return resetVoiceRecorder()}if(status)status.textContent=voiceText().sending;try{const audioData=await blobAsDataURL(blob);await addDoc(collection(db,"connections",connectionId,"messages"),{senderId:state.user.uid,text:"",audioData,audioType:blob.type||"audio/webm",duration:Math.min(20,Math.max(1,Math.round(duration))),createdAt:serverTimestamp()})}catch(error){console.error(error);toast(voiceText().failed)}finally{resetVoiceRecorder()}}
async function toggleVoiceRecording(connectionId){if(voiceRecorder?.state==="recording")return voiceRecorder.stop();if(!navigator.mediaDevices?.getUserMedia||!("MediaRecorder" in window))return toast(voiceText().unsupported);try{voiceStream=await navigator.mediaDevices.getUserMedia({audio:true});const type=voiceMimeType();voiceChunks=[];voiceRecorder=new MediaRecorder(voiceStream,type?{mimeType:type,audioBitsPerSecond:24000}:{audioBitsPerSecond:24000});voiceStartedAt=Date.now();voiceRecorder.ondataavailable=event=>{if(event.data.size)voiceChunks.push(event.data)};voiceRecorder.onstop=()=>sendVoiceRecording(connectionId,new Blob(voiceChunks,{type:voiceRecorder.mimeType||type||"audio/webm"}),(Date.now()-voiceStartedAt)/1000);voiceRecorder.start(500);const button=$("#recordVoice"),status=$("#voiceStatus");button.classList.add("recording");button.textContent="■";button.setAttribute("aria-label",voiceText().stop);const tick=()=>{if(voiceRecorder?.state!=="recording")return;if(status)status.textContent=voiceText().recording(Math.min(20,Math.ceil((Date.now()-voiceStartedAt)/1000)));voiceStopTimer=setTimeout(tick,500)};tick();voiceStopTimer=setTimeout(()=>{if(voiceRecorder?.state==="recording")voiceRecorder.stop()},20000)}catch(error){console.error(error);resetVoiceRecorder();toast(voiceText().permission)}}

