let pendingInstallPrompt=null;
function installedStandalone(){return window.matchMedia("(display-mode: standalone)").matches||window.navigator.standalone===true}
function mobileInstallInstructions(){const copy=installText(),ios=/iPad|iPhone|iPod/.test(navigator.userAgent);return ios?copy.ios:copy.android}
function updateInstallBanner(){const banner=$("#installBanner"),copy=installText();if(!banner)return;$("#installBannerTitle").textContent=copy.title;$("#installBannerText").textContent=pendingInstallPrompt?copy.intro:mobileInstallInstructions();$("#installBannerButton").textContent=pendingInstallPrompt?copy.install:copy.button;banner.hidden=installedStandalone()||localStorage.getItem("kindred_install_banner_dismissed")==="yes"||!matchMedia("(max-width: 768px)").matches}
