let notificationAudioContext=null;
async function unlockNotificationSound(){try{notificationAudioContext??=new (window.AudioContext||window.webkitAudioContext)();if(notificationAudioContext.state==="suspended")await notificationAudioContext.resume()}catch{}}
async function playNotificationSound(){await unlockNotificationSound();const audio=notificationAudioContext;if(!audio||audio.state!=="running")return false;try{const now=audio.currentTime,gain=audio.createGain();gain.gain.setValueAtTime(.0001,now);gain.gain.exponentialRampToValueAtTime(.32,now+.02);gain.gain.exponentialRampToValueAtTime(.0001,now+.9);gain.connect(audio.destination);[[0,783.99,.25],[.22,1046.5,.52],[.48,1318.5,.82]].forEach(([delay,frequency,end])=>{const oscillator=audio.createOscillator();oscillator.type="triangle";oscillator.frequency.setValueAtTime(frequency,now+delay);oscillator.connect(gain);oscillator.start(now+delay);oscillator.stop(now+end)});setTimeout(()=>gain.disconnect(),1100);return true}catch{return false}}
async function testNotificationSound(){await playNotificationSound();toast(soundText().played)}
function browserNotificationsEnabled(){return "Notification" in window&&Notification.permission==="granted"&&localStorage.getItem("kindred_browser_notifications")==="on"}
function updateNotificationToggle(){const button=$("#enableBrowserNotifications");if(!button)return;const copy=notificationText();if(!("Notification" in window)){button.textContent=copy.unsupported;button.disabled=true;return}button.disabled=Notification.permission==="denied";button.textContent=Notification.permission==="denied"?copy.denied:browserNotificationsEnabled()?copy.on:copy.enable}
async function enableBrowserNotifications(){const copy=notificationText();if(!("Notification" in window))return toast(copy.unsupported);try{const permission=await Notification.requestPermission();if(permission==="granted"){localStorage.setItem("kindred_browser_notifications","on");toast(copy.enabled)}else if(permission==="denied")localStorage.removeItem("kindred_browser_notifications");updateNotificationToggle()}catch{toast(tr("genericError"))}}
function showBrowserNotification(title,body,tag=title,onClick=null){void playNotificationSound();if(!browserNotificationsEnabled())return;try{const notice=new Notification(title,{body,tag:`kindred-${tag}`});notice.onclick=()=>{window.focus();notice.close();onClick?.()}}catch{}}
function clearMessageNotificationWatchers(){state.messageNotificationUnsubs.forEach(unsub=>unsub());state.messageNotificationUnsubs.clear();state.latestMessageIds.clear();state.conversationPreviews.clear()}
function updateUnreadMessageBadge(){const total=[...state.unreadMessages.values()].reduce((sum,count)=>sum+count,0),badge=$("#unreadMessageCount");badge.textContent=total>99?"99+":String(total);badge.hidden=!total}
function syncMessageNotificationWatchers(){const accepted=new Map(state.connections.filter(x=>x.status==="accepted").map(x=>[x.id,x]));state.messageNotificationUnsubs.forEach((unsub,id)=>{if(!accepted.has(id)){unsub();state.messageNotificationUnsubs.delete(id);state.latestMessageIds.delete(id);state.unreadMessages.delete(id);state.conversationPreviews.delete(id)}});accepted.forEach((connection,id)=>{if(state.messageNotificationUnsubs.has(id))return;const unsubscribe=onSnapshot(query(collection(db,"connections",id,"messages"),orderBy("createdAt","desc"),limit(1)),snap=>{const latest=snap.docs[0],data=latest?.data();state.conversationPreviews.set(id,data?{text:data.text||voiceText().preview,time:data.createdAt?.toDate?.()||new Date(),ms:data.createdAt?.toMillis?.()||Date.now()}:null);renderConversationList();if(!state.latestMessageIds.has(id)){state.latestMessageIds.set(id,latest?.id||"");return}if(!latest||latest.id===state.latestMessageIds.get(id))return;state.latestMessageIds.set(id,latest.id);if(data.senderId===state.user?.uid)return;if(state.activeConnectionId!==id||state.currentPanel!=="messages"||document.hidden){state.unreadMessages.set(id,(state.unreadMessages.get(id)||0)+1);updateUnreadMessageBadge();renderConversationList()}const copy=notificationText();showBrowserNotification(copy.newMessage,copy.messageBody,`message-${id}`,()=>{showPanel("messages");openConversation(connection)})},()=>{});state.messageNotificationUnsubs.set(id,unsubscribe)});updateUnreadMessageBadge()}

