async function loadOwnProfile(){const snap=await getDoc(doc(db,"profiles",state.user.uid));state.profile=snap.exists()?snap.data():null;const p=state.profile;if(!p){state.pendingPhotoURL=safePhoto(state.user.photoURL||"");$("#timeZone").value=Intl.DateTimeFormat().resolvedOptions().timeZone||"UTC";updatePhotoPreview(state.pendingPhotoURL);return showPanel("profile")}$("#displayName").value=p.displayName||"";$("#profileCity").value=p.city||"";$("#profileCountry").value=p.country||"";$("#bio").value=p.bio||"";$("#interests").value=(p.interests||[]).join(", ");$("#languages").value=(p.languages||[]).join(", ");$("#availability").value=p.availability||"Flexible";$("#friendshipGoal").value=p.friendshipGoal||"close";$("#connectionMode").value=p.connectionMode||"both";$("#contactFrequency").value=p.contactFrequency||"flexible";$("#socialFormat").value=p.socialFormat||"both";$("#communicationStyle").value=p.communicationStyle||"mixed";$("#socialEnergy").value=p.socialEnergy||"balanced";$("#spontaneousInvites").value=p.spontaneousInvites||"sometimes";$("#conversationDepth").value=p.conversationDepth||"both";$("#newCityRole").value=p.newCityRole||"either";$("#timeZone").value=p.timeZone||Intl.DateTimeFormat().resolvedOptions().timeZone||"UTC";$("#meetingPace").value=p.meetingPace||"later";const available=new Set(p.availableTimes||["weekdayEvening","weekendDaytime"]);$$("input[name=\"availableTime\"]").forEach(input=>input.checked=available.has(input.value));$("#intercultural").checked=p.intercultural!==false;$("#namePronunciation").value=p.namePronunciation||"";$("#preferredContactTime").value=p.preferredContactTime||"flexible";$("#comfortableTopics").value=(p.comfortableTopics||[]).join(", ");$("#culturalContext").value=p.culturalContext||"";$("#adultConfirm").checked=p.adultConfirmed===true;$("#activeProfile").checked=p.active!==false;state.pendingPhotoURL=safePhoto(p.photoURL||state.user.photoURL||"");updatePhotoPreview(state.pendingPhotoURL)}

async function saveProfile(event){event.preventDefault();const data={displayName:$("#displayName").value.trim(),city:$("#profileCity").value.trim(),country:$("#profileCountry").value.trim(),bio:$("#bio").value.trim(),interests:cleanList($("#interests").value,12),languages:cleanList($("#languages").value,8),availability:$("#availability").value,friendshipGoal:$("#friendshipGoal").value,connectionMode:$("#connectionMode").value,contactFrequency:$("#contactFrequency").value,socialFormat:$("#socialFormat").value,communicationStyle:$("#communicationStyle").value,socialEnergy:$("#socialEnergy").value,spontaneousInvites:$("#spontaneousInvites").value,conversationDepth:$("#conversationDepth").value,newCityRole:$("#newCityRole").value,timeZone:$("#timeZone").value.trim()||Intl.DateTimeFormat().resolvedOptions().timeZone||"UTC",meetingPace:$("#meetingPace").value,availableTimes:selectedAvailableTimes(),intercultural:$("#intercultural").checked,namePronunciation:$("#namePronunciation").value.trim(),preferredContactTime:$("#preferredContactTime").value,comfortableTopics:cleanList($("#comfortableTopics").value,10),culturalContext:$("#culturalContext").value.trim(),photoURL:safePhoto(state.pendingPhotoURL||state.profile?.photoURL||state.user.photoURL||""),active:$("#activeProfile").checked,adultConfirmed:$("#adultConfirm").checked,updatedAt:serverTimestamp()};if(!data.adultConfirmed||data.bio.length<30||!data.interests.length||!data.languages.length||!data.availableTimes.length)return toast(tr("completeFields"));try{await setDoc(doc(db,"profiles",state.user.uid),data);state.profile={...data,updatedAt:new Date()};toast(tr("profileSaved"));showPanel("discover")}catch(error){toast(errorMessage(error))}}

function friendshipCompatibility(p){const mine=state.profile||{},reasons=[];let points=20,possible=20;const pairs=[["friendshipGoal","sameGoal"],["connectionMode","sameConnectionMode"],["contactFrequency","sameRhythm"],["socialFormat","sameSocialFormat"],["communicationStyle","sameCommunicationStyle"],["socialEnergy","sameEnergy"],["spontaneousInvites","sameSpontaneity"],["conversationDepth","sameDepth"]];pairs.forEach(([key,label])=>{if(mine[key]&&p[key]){possible+=8;if(mine[key]===p[key]||mine[key]==="both"||p[key]==="both"||mine[key]==="mixed"||p[key]==="mixed"){points+=8;reasons.push(tr(label))}}});const sharedInterests=(p.interests||[]).filter(x=>(mine.interests||[]).some(y=>y.toLowerCase()===x.toLowerCase())),sharedLanguages=(p.languages||[]).filter(x=>(mine.languages||[]).some(y=>y.toLowerCase()===x.toLowerCase()));possible+=20;if(sharedInterests.length){points+=10;reasons.push(tr("sharedInterestsReason",sharedInterests.slice(0,2).join(", ")))}if(sharedLanguages.length){points+=10;reasons.push(tr("sharedLanguagesReason",sharedLanguages.slice(0,2).join(", ")))}if(mine.timeZone&&p.timeZone){possible+=6;if(mine.timeZone===p.timeZone){points+=6;reasons.push(tr("sameTimeZone"))}}if(mine.intercultural&&p.intercultural){possible+=4;points+=4;reasons.push(tr("bothIntercultural"))}if(mine.meetingPace&&p.meetingPace){possible+=8;if(mine.meetingPace===p.meetingPace){points+=8;reasons.push(scheduleText().samePace)}}const sharedTimes=(p.availableTimes||[]).filter(time=>(mine.availableTimes||[]).includes(time));if((mine.availableTimes||[]).length&&(p.availableTimes||[]).length){possible+=10;if(sharedTimes.length){points+=10;reasons.push(scheduleText().sharedTime)}}return{score:Math.max(35,Math.min(98,Math.round(points/possible*100))),reasons:reasons.slice(0,3),sharedInterests}}
function profileCard(uid,p){const article=document.createElement("article");article.className="person card";const match=friendshipCompatibility(p),photo=safePhoto(p.photoURL),initial=escapeText((p.displayName||tr("member")).trim().charAt(0).toUpperCase());article.innerHTML=`<div class="person-head">${photo?`<img class="person-avatar" src="${escapeText(photo)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:`<span class="person-avatar person-avatar-fallback" aria-hidden="true">${initial}</span>`}<div><span class="eyebrow">${match.sharedInterests.length?tr("shared",match.sharedInterests.length):tr("newPossibility")}</span><h2>${escapeText(p.displayName)}</h2></div><strong class="match-score">${match.score}%</strong></div><p class="person-meta">${escapeText(p.city)}, ${escapeText(p.country)} · ${escapeText(availabilityText(p.availability))}</p><p>${escapeText(p.bio)}</p><div class="tags">${(p.interests||[]).map(x=>`<span class="tag">${escapeText(x)}</span>`).join("")}</div><p class="match-explanation"><strong>${tr("whyMatch")}</strong> ${escapeText(match.reasons.length?match.reasons.join(" · "):tr("completePassportHint"))}</p><p class="fine">${tr("languagesLabel")}: ${escapeText((p.languages||[]).join(", "))}</p><div class="person-actions"><button class="secondary view-profile">${escapeText(previewText().view)}</button><span class="favorite-slot"></span><button class="button connect">${tr("connect")}</button><button class="danger-link report">${tr("reportAction")}</button></div>`;article.querySelector(".favorite-slot").replaceWith(favoriteButton(uid));article.querySelector(".view-profile").onclick=()=>openProfilePreview(uid,p);article.querySelector(".connect").onclick=()=>sendRequest(uid,p);article.querySelector(".report").onclick=()=>openReport(uid,p.displayName);return article}

function updateNotificationBadge(){const badge=$("#newProfileCount");if(!badge)return;badge.hidden=state.newProfileCount<1;badge.textContent=state.newProfileCount>99?"99+":String(state.newProfileCount)}
function watchNewProfiles(){state.unsubProfiles?.();state.profileWatchReady=false;state.seenProfileIds=new Set();state.unsubProfiles=onSnapshot(query(collection(db,"profiles"),where("active","==",true),limit(60)),snap=>{const ids=new Set(snap.docs.map(x=>x.id).filter(id=>id!==state.user?.uid));if(!state.profileWatchReady){state.seenProfileIds=ids;state.profileWatchReady=true;return}const added=[...ids].filter(id=>!state.seenProfileIds.has(id));state.seenProfileIds=ids;if(!added.length)return;state.newProfileCount+=added.length;updateNotificationBadge();const message=tr("newMembers",added.length);toast(message);showBrowserNotification(notificationText().newMember,message);if(state.currentPanel==="discover")loadProfiles()},error=>toast(errorMessage(error)))}

async function loadBlocked(){const ids=new Set();const [mine,theirs]=await Promise.all([getDocs(query(collection(db,"blocks"),where("blockerId","==",state.user.uid),limit(100))),getDocs(query(collection(db,"blocks"),where("blockedId","==",state.user.uid),limit(100)))]);mine.forEach(x=>ids.add(x.data().blockedId));theirs.forEach(x=>ids.add(x.data().blockerId));return ids}
async function loadBlockedManagement(){const container=$("#blockedPeople");if(!container||!state.user)return;container.innerHTML=`<p class="fine">…</p>`;try{const snap=await getDocs(query(collection(db,"blocks"),where("blockerId","==",state.user.uid),limit(100))),items=await Promise.all(snap.docs.map(async block=>{const uid=block.data().blockedId;if(!state.profiles.has(uid)){const profile=await getDoc(doc(db,"profiles",uid));if(profile.exists())state.profiles.set(uid,profile.data())}return{blockId:block.id,uid}}));container.replaceChildren(...items.map(item=>{const row=document.createElement("article"),button=document.createElement("button");row.className="connection-row";row.innerHTML=`<div><strong>${escapeText(profileName(item.uid))}</strong></div>`;button.className="secondary";button.textContent=safetyText().unblock;button.onclick=()=>unblockPerson(item.blockId);row.append(button);return row}));if(!items.length)container.innerHTML=`<p class="fine">${escapeText(safetyText().noneBlocked)}</p>`}catch(error){container.innerHTML=`<p class="fine">${escapeText(errorMessage(error))}</p>`}}
async function unblockPerson(blockId){try{await deleteDoc(doc(db,"blocks",blockId));toast(safetyText().unblocked);await loadBlockedManagement();await loadProfiles()}catch(error){toast(errorMessage(error))}}
async function loadProfiles(){if(!state.user||!requireProfile())return;const status=$("#discoverStatus"),container=$("#profiles");status.textContent=tr("loadingProfiles");container.replaceChildren();try{const blocked=await loadBlocked();const snap=await getDocs(query(collection(db,"profiles"),where("active","==",true),limit(60)));state.profiles.clear();snap.forEach(x=>state.profiles.set(x.id,x.data()));const mode=$("#filterMode").value,city=$("#filterCity").value.trim().toLowerCase(),nearbyCity=city||(state.profile?.city||"").toLowerCase(),interest=$("#filterInterest").value.trim().toLowerCase(),language=$("#filterLanguage").value.trim().toLowerCase(),rhythm=$("#filterRhythm").value;const items=[...state.profiles].filter(([uid,p])=>uid!==state.user.uid&&!blocked.has(uid)&&(mode!=="nearby"||!nearbyCity||(p.city||"").toLowerCase().includes(nearbyCity))&&(mode!=="newcity"||["newcomer","localHelper","either"].includes(p.newCityRole))&&(!interest||(p.interests||[]).some(x=>x.toLowerCase().includes(interest)))&&(!language||(p.languages||[]).some(x=>x.toLowerCase().includes(language)))&&(!rhythm||p.contactFrequency===rhythm)).sort((a,b)=>friendshipCompatibility(b[1]).score-friendshipCompatibility(a[1]).score);container.replaceChildren(...items.map(([uid,p])=>profileCard(uid,p)));renderFavoriteProfiles();status.textContent=items.length?tr("profilesFound",items.length):tr("noProfiles")}catch(error){status.textContent=errorMessage(error)}}

async function sendRequest(uid,profile){if(!requireProfile())return;const id=pairId(state.user.uid,uid);try{await setDoc(doc(db,"connections",id),{participants:[state.user.uid,uid].sort(),requestedBy:state.user.uid,recipientId:uid,status:"pending",createdAt:serverTimestamp(),updatedAt:serverTimestamp()});toast(tr("requestSent",profile.displayName))}catch(error){if((error?.code||"").includes("permission-denied"))return toast(tr("requestExists"));toast(errorMessage(error))}}

function profileName(uid){return (uid===state.user?.uid?state.profile:state.profiles.get(uid))?.displayName||tr("member")}
function avatarMarkup(uid,className="chat-avatar"){const profile=uid===state.user?.uid?state.profile:state.profiles.get(uid),photo=safePhoto(profile?.photoURL),name=profile?.displayName||tr("member"),initial=escapeText(name.trim().charAt(0).toUpperCase()||"?");return photo?`<img class="${className}" src="${escapeText(photo)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:`<span class="${className} avatar-fallback" aria-hidden="true">${initial}</span>`}
function otherId(connection){return connection.participants.find(x=>x!==state.user.uid)}
function connectionRow(connection,mode){const other=otherId(connection),row=document.createElement("article");row.className="connection-row";row.innerHTML=`<div><strong>${escapeText(profileName(other))}</strong><div class="fine">${escapeText(connection.status)}</div></div>`;if(mode==="incoming"){const yes=document.createElement("button");yes.className="button";yes.textContent=tr("accept");yes.onclick=()=>answerRequest(connection.id,"accepted");const no=document.createElement("button");no.className="secondary";no.textContent=tr("decline");no.onclick=()=>answerRequest(connection.id,"declined");row.append(yes,no)}if(mode==="accepted"){const msg=document.createElement("button");msg.className="button";msg.textContent=tr("message");msg.onclick=()=>openConversation(connection);const report=document.createElement("button");report.className="danger-link";report.textContent=tr("reportAction");report.onclick=()=>openReport(other,profileName(other));const end=document.createElement("button");end.className="danger-link";end.textContent=safetyText().end;end.onclick=()=>endConnection(connection.id);row.append(msg,report,end)}if(mode==="outgoing"){const cancel=document.createElement("button");cancel.className="danger-link";cancel.textContent=safetyText().cancelRequest;cancel.onclick=()=>endConnection(connection.id);row.append(cancel)}return row}
function renderConnections(){const incoming=$("#incoming"),accepted=$("#accepted"),outgoing=$("#outgoing");if(!incoming||!accepted||!outgoing)return;[incoming,accepted,outgoing].forEach(x=>x.replaceChildren());let incomingCount=0;state.connections.forEach(c=>{if(c.status==="pending"&&c.recipientId===state.user?.uid){incoming.append(connectionRow(c,"incoming"));incomingCount++}else if(c.status==="accepted")accepted.append(connectionRow(c,"accepted"));else if(c.status==="pending")outgoing.append(connectionRow(c,"outgoing"))});$("#requestCount").textContent=incomingCount?`(${incomingCount})`:"";if(!incoming.children.length)incoming.innerHTML=`<p class="fine">${tr("noRequests")}</p>`;if(!accepted.children.length)accepted.innerHTML=`<p class="fine">${tr("noConnections")}</p>`;if(!outgoing.children.length)outgoing.innerHTML=`<p class="fine">${tr("noSent")}</p>`}
async function answerRequest(id,status){try{await updateDoc(doc(db,"connections",id),{status,updatedAt:serverTimestamp()});toast(tr(status==="accepted"?"accepted":"declined"))}catch(error){toast(errorMessage(error))}}
async function endConnection(id){if(!confirm(safetyText().confirmEnd))return;try{await deleteDoc(doc(db,"connections",id));if(state.activeConnectionId===id){state.activeConnectionId=null;state.unsubMessages?.();$("#conversation").innerHTML=`<p>${escapeText(tr("selectConnection"))}</p>`}toast(safetyText().ended)}catch(error){toast(errorMessage(error))}}
function watchConnections(){state.unsubConnections?.();state.connectionWatchReady=false;state.incomingRequestIds=new Set();state.unsubConnections=onSnapshot(query(collection(db,"connections"),where("participants","array-contains",state.user.uid)),snap=>{state.connections=snap.docs.map(x=>({id:x.id,...x.data()}));const incoming=new Set(state.connections.filter(x=>x.status==="pending"&&x.recipientId===state.user.uid).map(x=>x.id));if(state.connectionWatchReady){const added=[...incoming].filter(id=>!state.incomingRequestIds.has(id));if(added.length)showBrowserNotification(notificationText().newRequest,notificationText().requestBody)}else state.connectionWatchReady=true;state.incomingRequestIds=incoming;syncMessageNotificationWatchers();renderConnections();renderConversationList();renderGrowingFriendships();if(state.currentPanel==="messages"&&state.activeConnectionId){const current=state.connections.find(x=>x.id===state.activeConnectionId);if(current)openConversation(current)}},error=>toast(errorMessage(error)))}

