async function saveAgreement(event,connectionId){event.preventDefault();const form=event.currentTarget,data={frequency:form.frequency.value,meeting:form.meeting.value,format:form.format.value,closeness:form.closeness.value,voice:form.voice.value,spontaneous:form.spontaneous.value,boundaries:form.boundaries.value.trim(),updatedAt:new Date().toISOString()},update={updatedAt:serverTimestamp()};update["agreements."+state.user.uid]=data;try{await updateDoc(doc(db,"connections",connectionId),update);toast(tr("agreementSaved"))}catch(error){toast(errorMessage(error))}}
