function activityText(){return activityCopy[locale]||activityCopy.en}
function activityCard(){const copy=activityText();return `<details class="activity-card"><summary>${escapeText(copy.title)}</summary><div class="activity-form"><select id="activityMode"><option value="online">${escapeText(copy.online)}</option><option value="offline">${escapeText(copy.offline)}</option></select><input id="activityName" maxlength="200" placeholder="${escapeText(copy.placeholder)}"><input id="activityWhen" type="datetime-local"><button id="insertActivity" class="secondary" type="button">${escapeText(copy.insert)}</button></div><p class="activity-safety">${escapeText(copy.safety)}</p></details>`}
function insertActivity(){const copy=activityText(),mode=$("#activityMode").value,activity=$("#activityName").value.trim(),when=$("#activityWhen").value,message=$("#messageText");if(!activity)return $("#activityName").focus();let text=`🗓️ ${copy.invite} ${activity} (${copy.mode[mode]})`;if(when){const date=new Date(when),formatted=new Intl.DateTimeFormat(locale,{dateStyle:"medium",timeStyle:"short"}).format(date);text+=` — ${copy.when} ${formatted}`}message.value=text;message.focus();message.setSelectionRange(text.length,text.length)}
openConversation=function(connection){openConversationWithoutJourney(connection);const other=otherId(connection),agreements=connection.agreements||{},ready=Boolean(agreements[state.user.uid]&&agreements[other]);if(!ready)return;const locked=$(".chat-locked"),icebreakerHolder=document.createElement("div"),recommendationHolder=document.createElement("div"),activityHolder=document.createElement("div"),cultureHolder=document.createElement("div"),journeyHolder=document.createElement("div");icebreakerHolder.innerHTML=icebreakerCard(connection);recommendationHolder.innerHTML=recommendationCard();activityHolder.innerHTML=activityCard();cultureHolder.innerHTML=culturalBridgeCard(other);journeyHolder.innerHTML=journeyCard(connection,true);locked.before(journeyHolder.firstElementChild,icebreakerHolder.firstElementChild,recommendationHolder.firstElementChild,activityHolder.firstElementChild,cultureHolder.firstElementChild);$("#answerIcebreaker").onclick=()=>$("#messageText")?.focus();$("#insertRecommendation").onclick=insertRecommendation;$("#insertActivity").onclick=insertActivity;configureJourneyCheckIn(connection);$("#journeyForm").onsubmit=event=>saveJourney(event,connection.id)};

function openReport(uid,name){state.reportTarget=uid;$("#reportTarget").textContent=tr("reportIntro",name);$("#reportDialog").showModal()}
async function submitReport(event){if(event.submitter?.value==="cancel")return;event.preventDefault();const details=$("#reportDetails").value.trim(),reason=$("#reportReason").value;if(!reason||details.length<20)return toast(tr("reportValidation"));try{await addDoc(collection(db,"reports"),{reporterId:state.user.uid,reportedId:state.reportTarget,reason,details,status:"open",createdAt:serverTimestamp()});if($("#alsoBlock").checked){await setDoc(doc(db,"blocks",`${state.user.uid}_${state.reportTarget}`),{blockerId:state.user.uid,blockedId:state.reportTarget,createdAt:serverTimestamp()});await deleteDoc(doc(db,"connections",pairId(state.user.uid,state.reportTarget)))}$("#reportDialog").close();event.target.reset();toast(tr("reportSubmitted"));loadProfiles();if(state.currentPanel==="connections")loadBlockedManagement()}catch(error){toast(errorMessage(error))}}

