window.addEventListener("beforeinstallprompt",event=>{event.preventDefault();pendingInstallPrompt=event;$("#installKindred").hidden=false;updateInstallBanner()});
window.addEventListener("appinstalled",()=>{pendingInstallPrompt=null;$("#installKindred").hidden=true;$("#installBanner").hidden=true});
if("serviceWorker" in navigator)window.addEventListener("load",()=>navigator.serviceWorker.register("service-worker.js").catch(()=>{}));
applyLanguage(locale);

onAuthStateChanged(auth,async user=>{state.user=user;$("#signedOut").hidden=!!user;$("#signedIn").hidden=!user;$("#notificationBell").hidden=!user;$("#enableBrowserNotifications").hidden=!user;$("#testNotificationSound").hidden=!user;updateNotificationToggle();$("#authButton").textContent=user?tr("signOut"):tr("signIn");state.unsubMessages?.();state.unsubConnections?.();state.unsubProfiles?.();clearMessageNotificationWatchers();state.unreadMessages.clear();updateUnreadMessageBadge();if(!user){state.profile=null;state.favorites=new Set();state.pendingPhotoURL="";state.profileWatchReady=false;state.seenProfileIds=new Set();state.newProfileCount=0;state.connectionWatchReady=false;state.incomingRequestIds=new Set();updateNotificationBadge();updateFavoritesLabels();updatePhotoPreview("");return}try{await savePrivateUser(user);await loadFavorites();await loadOwnProfile();watchConnections();watchNewProfiles();await loadProfiles()}catch(error){toast(errorMessage(error))}});
